import{describe,it,expect,beforeEach}from"vitest";describe("Journey / Bookmark System Unit Tests",()=>{let e={};beforeEach(()=>{e={},globalThis.localStorage={getItem:t=>e[t]||null,setItem:(t,r)=>{e[t]=String(r)},removeItem:t=>{delete e[t]},clear:()=>{e={}}}}),it("saves and retrieves items from journey store",()=>{const e="ii-journey-items",t=JSON.parse(localStorage.getItem(e)||"[]");t.push({id:"startup-1",title:"AgriTech India",category:"startup"}),localStorage.setItem(e,JSON.stringify(t));const r=JSON.parse(localStorage.getItem(e));expect(r).toHaveLength(1),expect(r[0].title).toBe("AgriTech India")}),it("prevents duplicate bookmarks",()=>{const e={id:"startup-1",title:"AgriTech India"};let t=[e];var r;r=e,t.some(e=>e.id===r.id)||t.push(r),expect(t).toHaveLength(1)}),it("removes item from journey store",()=>{let e=[{id:"startup-1",title:"AgriTech India"},{id:"startup-2",title:"HealthAI"}];var t;t="startup-1",e=e.filter(e=>e.id!==t),expect(e).toHaveLength(1),expect(e[0].id).toBe("startup-2")})});